$\begin{aligned}
& \frac{\mathrm{d} y}{\mathrm{~d} x}=y \tan x-y^2 \sec x \\
& \Rightarrow \frac{1}{y^2} \cdot \frac{\mathrm{~d} y}{\mathrm{~d} x}+\tan x\left(-\frac{1}{y}\right)=-\sec x \ldots (i)\\
& \text { Put } \mathrm{v}=-\frac{1}{y} \Rightarrow \frac{\mathrm{dv}}{\mathrm{~d} x}=\frac{1}{y^2} \cdot \frac{\mathrm{~d} y}{\mathrm{~d} x}
\end{aligned}\therefore \quad \frac{\mathrm{dv}}{\mathrm{d} x}+(\tan x) \mathrm{v}=-\sec x \quad \ldots[$ From (i) $]\therefore \quad$ I.F. $=\mathrm{e}^{\int \tan x \mathrm{dx}}=\mathrm{e}^{\log (\sec x)}=\sec x\therefore \quad$ solution of the given equation is
$\begin{aligned} & \text { v. } \sec x=\int-\sec x \cdot \sec x \mathrm{~d} x+\mathrm{c}_1 \\ & \Rightarrow \mathrm{v} \sec x=-\tan x+\mathrm{c}_1 \\ & \Rightarrow-\frac{1}{y} \sec x=-\tan x+\mathrm{c}_1 \\ & \Rightarrow \sec x=y(\tan x+\mathrm{c}), \text { where } \mathrm{c}=-\mathrm{c}_1\end{aligned}$

$\begin{aligned}
y & =\left(C_1+C_2\right) \mathrm{e}^x+\mathrm{C}_3 \mathrm{e}^{x+\mathrm{C}_4} \\
& =\mathrm{Ae}^x+\mathrm{Be}^x \text {, where } \mathrm{A}=\mathrm{C}_1+\mathrm{C}_2 \text { and } \mathrm{B}=\mathrm{C}_3 \mathrm{e}^{\mathrm{C}_4} \\
& =(\mathrm{A}+\mathrm{B}) \mathrm{e}^x \\
& =\mathrm{De}^x, \text { where } \mathrm{D}=\mathrm{A}+\mathrm{B}
\end{aligned}$<br/>This equation consist of one arbitrary constant.

Let M be the mass of substance at time t . Then,
$\begin{aligned}
& \frac{\mathrm{dM}}{\mathrm{dt}}=-\mathrm{kM}, \text { where } \mathrm{k}\gt0 \\
& \Rightarrow \frac{\mathrm{dM}}{\mathrm{M}}=-\mathrm{kdt}
\end{aligned}$<br/>Integrating on both sides, we get
$\log M=-k t+c$<br/>When $\mathrm{t}=0, \mathrm{M}=\mathrm{m}_0\begin{array}{ll}
\therefore \quad & \log \mathrm{m}_0=0+c \\
& \Rightarrow \mathrm{c}=\log \mathrm{m}_0 \\
\therefore \quad & \log \mathrm{M}=-\mathrm{kt}+\log \mathrm{m}_0 \\
& \Rightarrow \log \frac{M}{\mathrm{~m}_0}=-\mathrm{kt}
\end{array}
$\begin{gathered}
\text { When } \mathrm{t}=\mathrm{h}, \mathrm{M}=\frac{1}{2} \mathrm{~m}_0 \\
\therefore \quad \log \left(\frac{\frac{1}{2} \mathrm{~m}_0}{\mathrm{~m}_0}\right)=-\mathrm{kh} \\
\Rightarrow \log \frac{1}{2}=-\mathrm{kh} \\
\Rightarrow \log 2=\mathrm{kh} \\
\Rightarrow \mathrm{k}=\frac{\log 2}{\mathrm{~h}} ...(i)\\
\mathrm{Initial} \text { decay rate, } \\
\frac{\mathrm{dM}}{\mathrm{dt}}=-\mathrm{km} \mathrm{~m}_0 \\
=\frac{-\mathrm{m}_0}{\mathrm{~h}} \log 2...[From(i)]
\end{gathered}

$\begin{array}{ll} 
& \mathrm{e}^{y-x} \frac{\mathrm{~d} y}{\mathrm{~d} x}=y\left(\frac{\sin x+\cos x}{1+y \log y}\right) \\
\therefore & \frac{\mathrm{e}^y}{\mathrm{e}^x} \frac{\mathrm{~d} y}{\mathrm{~d} x}=\frac{y}{(1+y \log y)}(\sin x+\cos x) \\
\therefore & \mathrm{e}^y \frac{(1+y \log y)}{y} \mathrm{~d} y=\mathrm{e}^x(\sin x+\cos x) \mathrm{d} x \\
\therefore \quad & \mathrm{e}^y\left(\log y+\frac{1}{y}\right) \mathrm{d} y=\mathrm{e}^x(\sin x+\cos x) \mathrm{d} x
\end{array} \\ Integrating both sides, we get
$\begin{aligned}
& \mathrm{e}^y \log y=\mathrm{e}^x \sin x+\mathrm{c} \\
& \quad \ldots\left[\because \int \mathrm{e}^x\left[\mathrm{f}(x)+\mathrm{f}^{\prime}(x)\right] \mathrm{d} x=\mathrm{e}^x \mathrm{f}(x)+\mathrm{c}\right]
\end{aligned}

$\begin{aligned}
& \cos x \frac{\mathrm{~d} y}{\mathrm{~d} x}-y \sin x=6 x \\
& \Rightarrow \frac{\mathrm{~d} y}{\mathrm{~d} x}-(\tan x) y=6 x \sec x
\end{aligned}$
This equation is of the form $\frac{\mathrm{d} y}{\mathrm{~d} x}+\mathrm{p} y=\mathrm{Q}\therefore \quad \text { If }=\mathrm{e}^{\int \mathrm{pdx}}=\mathrm{e}^{-\int \tan x d x}=\mathrm{e}^{\log x \cos x}=\cos x\therefore \quad$ Solution of given equation is
$\begin{aligned}
& y \cdot \cos x=\int 6 x \times \sec x \times \cos x \mathrm{~d} x+\mathrm{c} \\
& \Rightarrow y \cos x=\int 6 x \mathrm{~d} x+\mathrm{c} \\
& \Rightarrow y \cos x=3 x^2+\mathrm{c}
\end{aligned}$

Let $m$ be the mass of substance at time $t$. Then,
$\begin{aligned}
& \frac{\mathrm{dm}}{\mathrm{dt}}=-\mathrm{km} \text {, where } \mathrm{k}\gt0 \\
& \Rightarrow \frac{\mathrm{dm}}{\mathrm{~m}}=-\mathrm{kdt}
\end{aligned}$<br/>Integrating on both sides, we get
$\log m=-k t+c$<br/>When $\mathrm{t}=0, \mathrm{~m}=\mathrm{m}_0\begin{array}{ll}
\therefore \quad & \log \mathrm{m}_0=0+c \\
& \Rightarrow \mathrm{c}=\log \mathrm{m}_0 \\
\therefore \quad & \log \mathrm{~m}=-\mathrm{kt}+\log \mathrm{m}_0 \\
& \Rightarrow \log \frac{\mathrm{~m}}{\mathrm{~m}_0}=-\mathrm{kt}
\end{array}
$\begin{gathered}
\text { When } \mathrm{t}=\mathrm{h}, \mathrm{~m}=\frac{1}{2} \mathrm{~m}_0 \\
\therefore \quad \log \left(\frac{\frac{1}{2} \mathrm{~m}_0}{\mathrm{~m}_0}\right)=-\mathrm{kh} \\
\Rightarrow \log \frac{1}{2}=-\mathrm{kh} \\
\Rightarrow \log 2=\mathrm{kh} \\
\Rightarrow \mathrm{k}=\frac{\log 2}{\mathrm{~h}} ...(i)\\
\text { Initial decay rate } \\
\frac{\mathrm{dm}}{\mathrm{dt}}=-\mathrm{km} \mathrm{~m}_0 \\
=\frac{-\mathrm{m}_0}{\mathrm{~h}} \log 2...[From(i)]
\end{gathered}

$\begin{aligned} & x \frac{\mathrm{~d} y}{\mathrm{~d} x}+2 y=x^2 \\ & \frac{\mathrm{~d} y}{\mathrm{~d} x}+\left(\frac{2}{x}\right) y=x \\ & \text { I.F. }=\mathrm{e}^{\int \frac{2}{x} \mathrm{~d} x}=\mathrm{e}^{2 \log x}=x^2\end{aligned}\therefore \quad$ Solution of differential equation is
$\begin{aligned}
& \quad y \cdot x^2=\int x \cdot x^2 \mathrm{~d} x+\mathrm{c} \\
& \quad y x^2=\frac{x^4}{4}+\mathrm{c} ...(i)\\
& \therefore \quad \\
& y=\frac{x^2}{4}+\frac{\mathrm{c}}{x^2}
...(ii)\end{aligned}\begin{aligned} & \text { Given, } y(1)=1 \\ & \Rightarrow 1=\frac{1}{4}+\mathrm{c} \\ & \Rightarrow \mathrm{c}=\frac{3}{4}\end{aligned}\therefore \quad$ equation (i) becomes,
$\begin{aligned}
& y=\frac{x^2}{4}+\frac{3}{4 x^2} \\
\therefore \quad & y\left(\frac{1}{2}\right)=\frac{\left(\frac{1}{2}\right)^2}{4}+\frac{3}{4 \times\left(\frac{1}{2}\right)^2}=\frac{1}{16}+3=\frac{49}{16}
\end{aligned}$

$\begin{aligned}
& \left(1+y^2\right)(1+\log x) \mathrm{d} x+x \mathrm{~d} y=0 \\
& \Rightarrow\left(1+y^2\right)(1+\log x) \mathrm{d} x=-x \mathrm{~d} y \\
& \Rightarrow\left(\frac{1+\log x}{x}\right) \mathrm{d} x=\left(\frac{-1}{1+y^2}\right) \mathrm{d} y
\end{aligned}$<br/>Integrating on both sides, we get
$\Rightarrow \int \frac{(1+\log x)}{x} \mathrm{~d} x=-1 \int \frac{1}{1+y^2} \mathrm{~d} y\Rightarrow \int \mathrm{tdt}=-\tan ^{-1} y+\mathrm{c} \quad \cdots\left[\begin{array}{l}\text {Let } 1+\log x=\mathrm{t} \\ \frac{1}{x} \mathrm{~d} x=\mathrm{dt}\end{array}\right]\begin{aligned}
& \Rightarrow \frac{\mathrm{t}^2}{2}=-\tan ^{-1} y+\mathrm{c}...(i) \\
& \Rightarrow \frac{(1+\log x)^2}{2}=-\tan ^{-1} y+\mathrm{c}
\end{aligned}\begin{aligned}
& \text { At } x=1, y=1 \\
& \Rightarrow \frac{(1+\log 1)^2}{2}=-\tan ^{-1}(1)+c \\
& \Rightarrow c=\frac{1}{2}+\frac{\pi}{4}
\end{aligned}$<br/>Substituting above value in (i), we get
$\begin{aligned}
& \frac{(1+\log x)^2}{2}=-\tan ^{-1} y+\frac{1}{2}+\frac{\pi}{4} \\
& \frac{1}{2}+\log x+\frac{(\log x)^2}{2}=-\tan ^{-1} y+\frac{1}{2}+\frac{\pi}{4} \\
& \Rightarrow \log x+\frac{(\log x)^2}{2}+\tan ^{-1} y=\frac{\pi}{4}
\end{aligned}$

Let $\theta$ be the temperature of the body at any time $t$.
$\begin{aligned}
\therefore \quad & \frac{\mathrm{d} \theta}{\mathrm{dt}} \propto(\theta-20) \\
& \Rightarrow \frac{\mathrm{d} \theta}{\mathrm{dt}}=-\mathrm{k}(\theta-20), \mathrm{k}\gt0
\end{aligned}$
Integrating on both sides, we get
$\begin{aligned}
& \log |\theta-20|=-\mathrm{kt}+\mathrm{c} \\
& \text {When } \mathrm{t}=0, \theta=100^{\circ} \\
& \therefore \quad \log 80=-\mathrm{k}(0)+\mathrm{c} \\
& \Rightarrow \mathrm{c}=\log 80
\end{aligned}\begin{array}{ll}
\therefore \quad & \log |\theta-20|=-\mathrm{kt}+\log 80 \\
& \text {When } \mathrm{t}=15, \theta=60^{\circ} \\
\therefore \quad & \log 40=-15 \mathrm{k}+\log 80 \\
\Rightarrow & \mathrm{k}=\frac{-1}{15} \log \frac{1}{2}
\end{array}
$\begin{aligned} \therefore \quad & \log |\theta-20|=\frac{\mathrm{t}}{15} \log \frac{1}{2}+\log 80 \ldots[\text { From }(\mathrm{i})] \\ & \text { When } \mathrm{t}=1 \text { hour }=60 \text { minutes, } \\ & \log |\theta-20|=\frac{60}{15} \log \frac{1}{2}+\log 80 \\ & \Rightarrow \log \left(\frac{\theta-20}{80}\right)=4 \log \frac{1}{2} \\ & \Rightarrow \frac{\theta-20}{80}=\left(\frac{1}{2}\right)^4 \\ & \Rightarrow \theta=5+20=25^{\circ} \mathrm{C}\end{aligned}

$\begin{aligned} & x=\sec \theta-\cos \theta \text { and } y=\sec ^{10} \theta-\cos ^{10} \theta \\ \therefore \quad & \frac{\mathrm{~d} x}{\mathrm{~d} \theta}=\sec \theta \tan \theta+\sin \theta \text { and } \\ & \frac{\mathrm{d} y}{\mathrm{~d} \theta}=10 \sec ^9 \theta \cdot \sec \theta \tan \theta-10 \cos ^9 \theta \cdot(-\sin \theta)\end{aligned}\begin{aligned}
& =10 \sec ^{10} \theta \tan \theta+10 \cos ^9 \theta \sin \theta \\
& \therefore \quad \frac{\mathrm{~d} y}{\mathrm{~d} x}=\frac{\frac{\mathrm{d} y}{\mathrm{~d} \theta}}{\frac{\mathrm{~d} x}{\mathrm{~d} \theta}}=\frac{10 \sec ^{10} \theta \tan \theta+10 \cos ^9 \theta \sin \theta}{\sec \theta \tan \theta+\sin \theta}
\end{aligned}=\frac{10\left(\sec ^{10} \theta+\cos ^{10} \theta\right)}{\sec \theta+\cos \theta}\begin{aligned} \therefore \quad\left(\frac{\mathrm{d} y}{\mathrm{~d} x}\right)^2 & =\frac{10^2\left(\sec ^{10} \theta+\cos ^{10} \theta\right)^2}{(\sec \theta+\cos \theta)^2} \\ & =\frac{100\left[\left(\sec ^{10} \theta-\cos ^{10} \theta\right)^2+4 \sec ^{10} \theta \cos ^{10} \theta\right]}{(\sec \theta-\cos \theta)^2+4 \sec \theta \cos \theta}\end{aligned}\begin{aligned} \therefore \quad & \left(\frac{d y}{d x}\right)^2=\frac{100\left(y^2+4\right)}{x^2+4} \\ & \Rightarrow\left(x^2+4\right)\left(\frac{d y}{d x}\right)^2=100\left(y^2+4\right) \Rightarrow \mathrm{k}=100\end{aligned}$

Given differential equation is
$\frac{\mathrm{d} y}{\mathrm{~d} x}=(x-y)^2$<br/>Let $x-y=\mathrm{t}\begin{aligned}
\therefore \quad & 1-\frac{\mathrm{d} y}{\mathrm{~d} x}=\frac{\mathrm{dt}}{\mathrm{~d} x} \\
& \Rightarrow \frac{\mathrm{~d} y}{\mathrm{~d} x}=1-\frac{\mathrm{dt}}{\mathrm{~d} x}
\end{aligned}$<br/>From (i)
$\begin{aligned}
& 1-\frac{\mathrm{dt}}{\mathrm{~d} x}=\mathrm{t}^2 \\
& 1-\mathrm{t}^2=\frac{\mathrm{dt}}{\mathrm{dx}}
\end{aligned}\therefore \quad \mathrm{d} x=\frac{1}{1-\mathrm{t}^2} \mathrm{dt}$
Integrating on both sides, we get
$\begin{aligned}
& \int \mathrm{d} x=\int \frac{1}{1-\mathrm{t}^2} \mathrm{dt} \\
& x=\frac{1}{2} \log \left|\frac{1+\mathrm{t}}{1-\mathrm{t}}\right|+\mathrm{c} \\
& x=\frac{1}{2} \log \left|\frac{1+x-y}{1-(x-y)}\right|+\mathrm{c} \\
& x=\frac{1}{2} \log \left|\frac{1+x-y}{1-x+y}\right|+\mathrm{c}
\end{aligned}\text { But } y(1)=1\begin{aligned}
& \therefore \quad c=1 \\
& x=\frac{1}{2} \log \left|\frac{1+x-y}{1-x+y}\right|+1 \\
& x-1=\frac{1}{2} \log \left|\frac{1+x-y}{1-x+y}\right| \\
& 2(x-1)=\log \left|\frac{1+x-y}{1-x+y}\right| \\
& \Rightarrow-\log \left|\frac{1-x+y}{1+x-y}\right|=2(x-1)
\end{aligned}$

\begin{aligned}
& \cos x(1+\cos y) \mathrm{d} x-\sin y(1+\sin x) \mathrm{d} y=0 \\
& \Rightarrow \frac{\cos x}{1+\sin x} \mathrm{~d} x-\frac{\sin y}{1+\cos y} \mathrm{~d} y=0
\end{aligned}

Integrating on both sides, we get

\begin{aligned}
& \log |1+\sin x|+\log |1+\cos y|=\log |c| \\
& \Rightarrow \log |(1+\sin x)(1+\cos y)|=\log |c| \\
& \Rightarrow(1+\sin x)(1+\cos y)=c
\end{aligned}

\begin{aligned}
& x^2+y^2+\mathrm{a} x+\mathrm{b} y=0 \\
& \Rightarrow\left(x+\frac{\mathrm{a}}{2}\right)^2+\left(y+\frac{\mathrm{b}}{2}\right)^2=\frac{\mathrm{a}^2+\mathrm{b}^2}{4}
\end{aligned}

Comparing with $(x-\mathrm{h})^2+(y-\mathrm{k})^2=\mathrm{r}^2$, we get

\mathrm{h}=-\frac{\mathrm{a}}{2}, \mathrm{k}=-\frac{\mathrm{b}}{2}, \mathrm{r}=\sqrt{\frac{\mathrm{a}^2+\mathrm{b}^2}{4}}

$\therefore \quad$ The parametric equations are

x=-\frac{\mathrm{a}}{2}+\sqrt{\frac{\mathrm{a}^2+\mathrm{b}^2}{4}} \cos \theta, y=-\frac{\mathrm{b}}{2}+\sqrt{\frac{\mathrm{a}^2+\mathrm{b}^2}{4}} \sin \theta

\begin{aligned}
& \mathrm{e}^{-x}(y+1) \mathrm{d} y+\left(\cos ^2 x-\sin 2 x\right) y \mathrm{~d} x=0 \\
& \Rightarrow \frac{y+1}{y} \mathrm{~d} y+\mathrm{e}^x\left(\cos ^2 x-\sin 2 x\right) \mathrm{d} x=0
\end{aligned}

Integrating on both sides, we get

\begin{aligned}
& \int\left(1+\frac{1}{y}\right) \mathrm{d} y+\int \mathrm{e}^x\left(\cos ^2 x-2 \sin x \cos x\right) \mathrm{d} x=\mathrm{c} \\
& \Rightarrow y+\log |y|+\mathrm{e}^x \cos ^2 x=\mathrm{c} \\
& \text { At } x=0, y=1 \\
\therefore \quad & 1+\log 1+\mathrm{e}^0 \cos ^2 0=\mathrm{c} \\
& \Rightarrow \mathrm{c}=2 \\
\therefore \quad & y+\log |y|+\mathrm{e}^x \cos ^2 x=2
\end{aligned}

\begin{aligned}
& \mathrm{e}^{\frac{\mathrm{d}}{\mathrm{d} x}}=(x+1) \\
& \Rightarrow \frac{\mathrm{d} y}{\mathrm{~d} x}=\log (x+1)
\end{aligned}

Integrating on both sides, we get

\begin{aligned}
\int \mathrm{d} y & =\int \log (x+1) \mathrm{d} x+\mathrm{c} \\
\Rightarrow y & =x \log (x+1)-\int \frac{x}{x+1} \mathrm{~d} x+\mathrm{c} \\
& =x \log (x+1)-\int \frac{x+1-1}{x+1} \mathrm{~d} x+\mathrm{c} \\
& =x \log (x+1)-\int\left(1-\frac{1}{x+1}\right) \mathrm{d} x+\mathrm{c} \\
y & =x \log (x+1)-x+\log (x+1)+\mathrm{c} .
\end{aligned}

Since $y(0)=3$, i.e., $y=3$ when $x=0$
\begin{aligned}
& 3=0+\mathrm{c} \Rightarrow \mathrm{c}=3 \\
& y=x \log (x+1)+\log (x+1)-x+3 \\
& y=(x+1) \log (x+1)-x+3
\end{aligned}

\begin{aligned}
& \cos (x+y) \mathrm{d} y=\mathrm{d} x \\
\therefore \quad & \frac{\mathrm{d} x}{\mathrm{~d} y}=\cos (x+y)
\end{aligned}

Put $x+y=\mathrm{u}$ Differentiating w.r.t. $y$, we get $\frac{\mathrm{d} x}{\mathrm{~d} y}+1=\frac{\mathrm{du}}{\mathrm{d} y}$
\therefore \quad \frac{\mathrm{d} x}{\mathrm{~d} y}=\frac{\mathrm{du}}{\mathrm{d} y}-1

Substituting (ii) and (iii) in (i), we get

\begin{aligned}
& \frac{\mathrm{du}}{\mathrm{d} y}-1=\cos \mathrm{u} \\
& \therefore \quad \frac{\mathrm{du}}{1+\operatorname{cosu}}=\mathrm{d} y \\
& \therefore \quad \frac{\mathrm{du}}{2 \cos ^2\left(\frac{\mathrm{u}}{2}\right)}=\mathrm{d} y
\end{aligned}

Integrating on both sides, we get

\begin{aligned}
& \quad \frac{1}{2} \int \sec ^2\left(\frac{\mathrm{u}}{2}\right) \mathrm{du}=\int \mathrm{d} y \\
& \therefore \quad y=\tan \left(\frac{x+y}{2}\right)+\mathrm{c}
\end{aligned}

Given differential equation is
$\begin{array}{ll} 
& \log \left(\frac{d y}{d x}\right)=a x+b y \\
\therefore \quad & \frac{d y}{d x}=e^{a x+b y} \\
\therefore \quad & \frac{d y}{d x}=e^{a x} \cdot e^{b y}
\end{array}
$\begin{aligned} & \therefore \quad \frac{\mathrm{d} y}{\mathrm{e}^{\mathrm{by}}}=\mathrm{e}^{\mathrm{ax}} \cdot \mathrm{d} x \\ & \mathrm{e}^{-\mathrm{by}} \mathrm{d} y-\mathrm{e}^{\mathrm{ax}} \mathrm{d} x=0 \\ & \text { Integrating both sides, we get } \\ & \int \mathrm{e}^{-\mathrm{by}} \mathrm{d} y-\int \mathrm{e}^{\mathrm{ax}} \mathrm{d} x=0 \\ & \frac{e^{-b y}}{-b}-\frac{e^{a x}}{a}+c=0 \\ & \text { i.e., } \frac{e^{-b y}}{b}+\frac{e^{x x}}{a}=c \\ & a e^{-b y}+b e^{a x}=a b c \\ & a e^{-b y}+b e^{a x}=c_1 \text {, where } c_1=a b c \\ & \end{aligned}

$\begin{array}{ll} 
& \left(1+y^2\right) \mathrm{d} x-x y \mathrm{~d} y=0 \\
\therefore \quad & \left(1+y^2\right) \mathrm{d} x=x y \mathrm{~d} y \\
\therefore \quad & \frac{1}{x} \mathrm{~d} x=\frac{y \mathrm{~d} y}{1+y^2}
\end{array}
Integrating both sides, we get
$\begin{aligned}
& \int \frac{1}{x} \mathrm{~d} x=\int \frac{y}{1+y^2} \mathrm{~d} y \\
& \log x=\frac{1}{2} \log \left(1+y^2\right)+\mathrm{c}
\end{aligned}\text { At } x=1, y=0...[Given]\begin{array}{ll}
\therefore & 0=\frac{1}{2} \log (1+0)+\mathrm{c} \\
\therefore & \quad \mathrm{c}=0 \\
\therefore & \log x=\frac{1}{2} \log \left(1+y^2\right) \\
\therefore & x^2=1+y^2 \\
\therefore & x^2-y^2=1,
\end{array}
Which is a rectangular hyperbola.

$\begin{aligned} & \frac{y}{x} \cdot \frac{\mathrm{d} y}{\mathrm{~d} x}=\frac{1+y^2}{1+x^2} \\ & \Rightarrow \frac{y}{1+y^2} \mathrm{~d} y=\frac{x}{1+x^2} \mathrm{~d} x \\ & \Rightarrow \frac{1}{2} \int \frac{2 y \mathrm{~d} y}{1+y^2}=\frac{1}{2} \int \frac{2 x}{1+x^2} \mathrm{~d} x \\ & \Rightarrow \frac{1}{2} \log \left|1+y^2\right|=\frac{1}{2} \log \left|1+x^2\right|+\frac{1}{2} \log c \\ & \Rightarrow \log \frac{1+y^2}{1+x^2}=\log c \\ & \Rightarrow \frac{1+y^2}{1+x^2}=C\end{aligned}$
Putting $x=2, y=1$ we get $C=\frac{2}{5}$
\begin{aligned}
& \Rightarrow \frac{1+y^2}{1+x^2}=\frac{2}{5} \\
& \Rightarrow 5\left(1+y^2\right)=2\left(1+x^2\right)
\end{aligned}

\cos (x+y) \frac{d y}{d x}=1

Put $x+y=V \Rightarrow 1+\frac{d y}{d x}=\frac{d V}{d x}$
\begin{aligned}
& \therefore \cos \mathrm{V}\left(\frac{\mathrm{dV}}{\mathrm{dx}}-1\right)=1 \Rightarrow \cos \mathrm{V}\left(\frac{\mathrm{dV}}{\mathrm{dx}}\right)=1+\cos \mathrm{V} \\
& \therefore \int \frac{\cos \mathrm{V}}{1+\cos \mathrm{V}} \mathrm{dV}=\int \mathrm{dx} \\
& \therefore \int\left[\frac{1+\cos \mathrm{V}}{1+\cos \mathrm{V}}-\frac{1}{1+\cos \mathrm{V}}\right] \mathrm{dV} \\
& =\int \mathrm{dx} \Rightarrow \int \mathrm{dV}-\frac{1}{2} \int \sec ^2 \frac{\mathrm{V}}{2} \mathrm{dV}=\int \mathrm{dx}
\end{aligned}

\begin{aligned}
& \therefore \mathrm{V}-\frac{1}{2} \frac{\tan \left(\frac{\mathrm{V}}{2}\right)}{\left(\frac{1}{2}\right)}=\mathrm{x}+\mathrm{c} \Rightarrow \mathrm{V}-\tan \left(\frac{\mathrm{V}}{2}\right)=\mathrm{x}+\mathrm{c} \\
& \Rightarrow \mathrm{x}+\mathrm{y}-\tan \left(\frac{\mathrm{x}+\mathrm{y}}{2}\right)=\mathrm{x}+\mathrm{c} \\
& \mathrm{y}=\tan \left(\frac{\mathrm{x}+\mathrm{y}}{2}\right)+\mathrm{c}
\end{aligned}

(x+y) d y+(x-y) d x=0

We have $\frac{d y}{d x}=-\frac{(x-y)}{x+y}$
Put $y=v x \Rightarrow \frac{d y}{d x}=v+x \frac{d v}{d x}$
\therefore v+x \frac{d v}{d x}=\frac{-(x-v x)}{x+v x}=\frac{-x(1-v)}{x(1+v)}=\frac{-(1-v)}{1+v}

$\therefore x \frac{d v}{d x}=\frac{-1+v}{1+v}-v=\frac{-1+v-v-v^2}{1+v} \Rightarrow x \frac{d v}{d x}=\frac{-\left(1+v^2\right)}{1+v}$
\therefore \int \frac{(1+v)}{1+v^2} d v=-\int \frac{d x}{x} \Rightarrow \int \frac{d v}{1+v^2}+\frac{1}{2} \int \frac{2 v}{1+v^2} d v=-\int \frac{d x}{x}

\begin{aligned}
& \therefore \tan ^{-1}(\mathrm{v})+\frac{1}{2} \log \left|1+\mathrm{v}^2\right|=-\log \mathrm{x}+\log \mathrm{c}_1 \\
& \quad \Rightarrow \tan ^{-1}\left(\frac{\mathrm{y}}{\mathrm{x}}\right)+\frac{1}{2} \log \left|1+\frac{\mathrm{y}^2}{\mathrm{x}^2}\right|=-\log \mathrm{x}+\log \mathrm{c}_1
\end{aligned}

2 \tan ^{-1}\left(\frac{y}{x}\right)+\log \left|\frac{x^2+y^2}{x^2}\right|+2 \log x=\log c \ldots\left[\because \log c=2 \log c_1\right]

\therefore 2 \tan ^{-1}\left(\frac{y}{x}\right)+\log \left|\frac{x^2+y^2}{x^2} \times x^2\right|=\log c

$\mathrm{v}=6 \mathrm{t}-\frac{\mathrm{t}^2}{6}$ and we know that $\mathrm{v}=\frac{\mathrm{ds}}{\mathrm{dt}}$
\begin{aligned}
& \therefore \int \mathrm{d} s=\int\left(6 \mathrm{t}-\frac{\mathrm{t}^2}{6}\right) \mathrm{dt} \\
